/// A view whose data bindings have not all loaded: loading until then, and
/// a failed load's problem with a retry.
class DtxBindingState extends StatelessWidget {
  const DtxBindingState({super.key, required this.failed});

  final SyncedBinding? failed;

  @override
  Widget build(BuildContext context) {
    final messages = datrixRuntime.messages;
    final binding = failed;
    final error = binding?.error;
    if (binding == null || error == null) {
      return Semantics(
        label: messages.key('framework.loading').text,
        liveRegion: true,
        child: const Center(child: CircularProgressIndicator()),
      );
    }
    final problem = error.problem;
    final title = problem == null ? messages.key('framework.failed').text : problem.title;
    final detail = problem?.detail ?? '';
    return Semantics(
      liveRegion: true,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(title, style: Theme.of(context).textTheme.titleMedium),
          if (detail.isNotEmpty) Text(detail),
          const SizedBox(height: 12),
          FilledButton(onPressed: binding.refresh, child: Text(messages.key('framework.retry').text)),
        ],
      ),
    );
  }
}

/// How a layout presents its nav on a phone.
enum DtxNavIdiom { bottomBar, drawer }

/// One nav link: its route, its label, and what it shows beside the label.
class DtxNavLink {
  const DtxNavLink({required this.path, required this.label, this.icon, this.visible = true, this.badge});

  final String path;
  final String label;
  final IconData? icon;
  final bool visible;
  final String? badge;
}

/// A layout: its view, with its nav as a bottom navigation bar or a drawer.
class DtxLayoutScaffold extends StatelessWidget {
  const DtxLayoutScaffold({super.key, required this.idiom, required this.links, required this.body});

  final DtxNavIdiom idiom;
  final List<DtxNavLink> links;
  final Widget body;

  static const IconData _defaultIcon = Icons.circle_outlined;

  Widget _label(DtxNavLink link) {
    final badge = link.badge;
    final icon = Icon(link.icon ?? _defaultIcon);
    return badge == null || badge.isEmpty ? icon : Badge(label: Text(badge), child: icon);
  }

  @override
  Widget build(BuildContext context) {
    final shown = links.where((link) => link.visible).toList();
    final location = GoRouter.of(context).routeInformationProvider.value.uri.path;
    final selected = shown.indexWhere((link) => link.path == location);
    final content = SafeArea(child: body);
    if (idiom == DtxNavIdiom.bottomBar && shown.length >= 2) {
      return Scaffold(
        body: content,
        bottomNavigationBar: NavigationBar(
          selectedIndex: selected < 0 ? 0 : selected,
          onDestinationSelected: (index) => GoRouter.of(context).go(shown[index].path),
          destinations: [for (final link in shown) NavigationDestination(icon: _label(link), label: link.label)],
        ),
      );
    }
    return Scaffold(
      appBar: AppBar(),
      drawer: Drawer(
        child: SafeArea(
          child: ListView(
            children: [
              for (final (index, link) in shown.indexed)
                ListTile(
                  leading: _label(link),
                  title: Text(link.label),
                  selected: index == selected,
                  onTap: () {
                    Navigator.of(context).pop();
                    GoRouter.of(context).go(link.path);
                  },
                ),
            ],
          ),
        ),
      ),
      body: content,
    );
  }
}

/// An app's root: its router, its toasts and its theme -- light or dark as
/// the device prefers -- rebuilt when the session's locale changes. The app's
/// name on the device is its native project's.
class DatrixApp extends StatelessWidget {
  const DatrixApp({super.key, required this.runtime, required this.theme, required this.darkTheme});

  final DatrixRuntime runtime;
  final ThemeData theme;
  final ThemeData darkTheme;

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: runtime.session,
      builder: (context, _) => MaterialApp.router(routerConfig: runtime.router, scaffoldMessengerKey: runtime.messengerKey, theme: theme, darkTheme: darkTheme, themeMode: ThemeMode.system),
    );
  }
}
